 ida_hexrays.mark_cfunc_dirty(a)
 hf=ida_hexrays.hexrays_failure_t();cf=ida_hexrays.decompile(a,hf)
 journal['after']={'failure':hf.desc(),'failure_ea':hf.errea,'pseudocode':str(cf) if cf else None,'sha256':hashlib.sha256(ida_bytes.get_bytes(a,b-a)).hexdigest()}
